import SwiftUI
import RePrompterCore

/// Details about the open prompt, the HCG AI status, and a local,
/// deterministic analysis of the text. Nothing here is generated by AI.
struct InspectorView: View {
    @Environment(AppModel.self) private var model

    var body: some View {
        let analysis = model.liveAnalysis
        ScrollView {
            VStack(alignment: .leading, spacing: 16) {
                PaneHeader("Inspector", systemImage: "sidebar.trailing")

                InspectorGroup(title: "Prompt", systemImage: "doc.text", items: details, empty: "")

                InspectorGroup(
                    title: HCGAI.serviceName,
                    systemImage: "bolt.horizontal.circle",
                    items: [model.repromptAvailability.message ?? "Connected."],
                    empty: "",
                    tint: Theme.accentSecondary
                )

                Divider()

                Text("Local analysis — runs on this Mac, not AI. Updates as you type.")
                    .font(.caption)
                    .foregroundStyle(Theme.textTertiary)
                    .fixedSize(horizontal: false, vertical: true)

                if model.originalText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    Text("Start typing to see the prompt’s objective, requirements and gaps.")
                        .font(.callout)
                        .foregroundStyle(Theme.textSecondary)
                        .fixedSize(horizontal: false, vertical: true)
                } else {
                    InspectorGroup(title: "Objective", systemImage: "scope", items: analysis.objective.map { [$0] } ?? [], empty: "No clear objective detected.")
                    InspectorGroup(title: "Requirements", systemImage: "checklist", items: analysis.requirements, empty: "None detected.")
                    InspectorGroup(title: "Constraints", systemImage: "hand.raised", items: analysis.constraints, empty: "None detected.")
                    InspectorGroup(title: "Expected output", systemImage: "doc.plaintext", items: analysis.outputExpectations, empty: "Not specified.")
                    InspectorGroup(title: "Missing information", systemImage: "questionmark.circle", items: analysis.missingInformation, empty: "Nothing obvious is missing.", tint: Theme.warning)
                    InspectorGroup(title: "Vague wording", systemImage: "exclamationmark.bubble", items: analysis.ambiguities.map { "\($0.note) \($0.suggestion)" }, empty: "None found.", tint: Theme.warning)
                }
            }
            .padding(14)
        }
        .background(Theme.surface)
    }

    private var details: [String] {
        let text = model.originalText
        let words = text.split(whereSeparator: { $0.isWhitespace }).count
        let lines = text.isEmpty ? 0 : text.components(separatedBy: "\n").count
        var items = [
            "Title: \(model.effectiveTitle)",
            "\(words) words · \(text.count) characters · \(lines) lines",
        ]
        if let record = model.currentRecord {
            items.append(model.hasUnsavedChanges ? "In your library, with unsaved changes" : "Saved in your library")
            items.append("Created \(record.createdAt.formatted(date: .abbreviated, time: .shortened))")
            items.append("Last saved \(record.updatedAt.formatted(date: .abbreviated, time: .shortened))")
        } else {
            items.append(model.draft.isBlank ? "New prompt" : "Not saved yet — kept automatically until you save")
        }
        return items
    }
}

struct InspectorGroup: View {
    let title: String
    let systemImage: String
    let items: [String]
    let empty: String
    var tint: Color = Theme.accent

    var body: some View {
        VStack(alignment: .leading, spacing: 5) {
            Label(title, systemImage: systemImage)
                .font(.subheadline.weight(.semibold))
                .foregroundStyle(tint)
            if items.isEmpty {
                Text(empty).font(.caption).foregroundStyle(Theme.textTertiary)
            } else {
                ForEach(Array(items.enumerated()), id: \.offset) { _, item in
                    Text(item)
                        .font(.caption)
                        .foregroundStyle(Theme.textPrimary)
                        .fixedSize(horizontal: false, vertical: true)
                        .textSelection(.enabled)
                }
            }
        }
        .accessibilityElement(children: .combine)
    }
}
